def robot_action(position_delta, rotation_delta=None, gripper_closed=False, base_velocity=None):
    return {
        "action.end_effector_position": np.asarray(position_delta, dtype=np.float32),
        "action.end_effector_rotation": np.zeros(3, dtype=np.float32) if rotation_delta is None else np.asarray(rotation_delta, dtype=np.float32),
        "action.gripper_close": np.asarray([1.0 if gripper_closed else 0.0], dtype=np.float32),
        "action.base_motion": np.zeros(4, dtype=np.float32) if base_velocity is None else np.asarray(base_velocity, dtype=np.float32),
        "action.control_mode": np.zeros(1, dtype=np.float32),
    }


def quaternion_error(target, current):
    target = np.asarray(target)
    target = target / np.linalg.norm(target)
    current = np.asarray(current)
    current = current / np.linalg.norm(current)
    vector = -target[3] * current[:3] + current[3] * target[:3] - np.cross(target[:3], current[:3])
    scalar = target[3] * current[3] + np.dot(target[:3], current[:3])
    if scalar < 0:
        vector = -vector
        scalar = -scalar
    length = np.linalg.norm(vector)
    if length < 0.000001:
        return np.zeros(3)
    return vector * (2.0 * np.arctan2(length, scalar) / length)


def servo_pose(target_position, target_quaternion=None, gripper_closed=False, max_steps=45, position_tolerance=0.016, rotation_tolerance=0.06, position_gain=12.0, rotation_gain=1.5, action_limit=0.65, stall_steps=14, min_progress=0.001, minimum_gripper_gap=None):
    target_position = np.asarray(target_position)
    best_error = 1000000.0
    last_progress = 0
    observation = get_observation()
    for index in range(max_steps):
        if minimum_gripper_gap is not None and np.sum(np.abs(observation["state.gripper_qpos"])) < minimum_gripper_gap:
            return {"status": "grip_lost", "steps": index, "observation": observation}
        position_error = target_position - observation["state.end_effector_position_relative"]
        rotation_error = np.zeros(3) if target_quaternion is None else quaternion_error(target_quaternion, observation["state.end_effector_rotation_relative"])
        position_distance = np.linalg.norm(position_error)
        rotation_distance = np.linalg.norm(rotation_error)
        if position_distance <= position_tolerance and rotation_distance <= rotation_tolerance:
            return {"status": "reached", "steps": index, "observation": observation}
        total_error = position_distance + 0.1 * rotation_distance
        if total_error < best_error - min_progress:
            best_error = total_error
            last_progress = index
        elif index - last_progress >= stall_steps:
            return {"status": "stalled", "steps": index, "observation": observation}
        observation, reward, terminated, truncated, info = step(robot_action(
            np.clip(position_error * position_gain, -action_limit, action_limit),
            np.clip(rotation_error * rotation_gain, -action_limit, action_limit),
            gripper_closed,
        ))
        if info.get("success") or terminated or truncated:
            return {"status": "success" if info.get("success") else "terminated", "steps": index + 1, "observation": observation}
    return {"status": "budget", "steps": max_steps, "observation": observation}


